2095: fn (mut g Gen) write_shareds() {
2096: 	mut done_types := []int{}
2097: 	for typ, base in g.shareds {
2098: 		if typ in done_types {
2099: 			continue
2100: 		}
2101: 		done_types << typ
2102: 		sh_typ := '__shared__${base}'
2103: 		mtx_typ := 'sync__RwMutex'
2104: 		g.shared_types.writeln('struct ${sh_typ} {')
2105: 		g.shared_types.writeln('\t${mtx_typ} mtx;')
2106: 		g.shared_types.writeln('\t${base} val;')
2107: 		g.shared_types.writeln('};')
2108: 		g.shared_functions.writeln('static inline voidptr __dup${sh_typ}(voidptr src, ${ast.int_type_name} sz) {')
2109: 		g.shared_functions.writeln('\t${sh_typ}* dest = builtin__memdup(src, sz);')
2110: 		g.shared_functions.writeln('\tsync__RwMutex_init(&dest->mtx);')
2111: 		g.shared_functions.writeln('\treturn dest;')
2112: 		g.shared_functions.writeln('}')
2113: 		g.typedefs.writeln('typedef struct ${sh_typ} ${sh_typ};')
2114: 	}
